	\begin{equation}
	\label{eq:qld-g-prime-bound}
		\sum_{g \notin \mathcal{G}'} \norm{ (\hat{S}_g)_{\alice \alice'} \ket{\hat{\psi}}}^2 \leq O(\delta_\ld + \delta_Q + md/q).
	\end{equation}





